class Solution:
    def coveringLength(self, a: str, b: str) -> int:
        m = len(b)
        prev = [0] * (m + 1)
        for x in a:
            cur = [0] * (m + 1)
            for j in range(1, m + 1):
                cur[j] = prev[j - 1] + 1 if x == b[j - 1] else max(prev[j], cur[j - 1])
            prev = cur
        return len(a) + m - prev[m]

