function coveringLength(a, b) {
  const n = a.length, m = b.length;
  // dp[i][j] = shortest supersequence of a[:i], b[:j]
  const dp = Array.from({length: n + 1}, (_, i) => Array.from({length: m + 1}, (_, j) => i + j));
  for (let i = 1; i <= n; i++) for (let j = 1; j <= m; j++)
    dp[i][j] = a[i-1] === b[j-1] ? dp[i-1][j-1] + 1 : 1 + Math.min(dp[i-1][j], dp[i][j-1]);
  return dp[n][m];
}
